def build_array():
    out = []
    for ds in DATASETS:
        for i, (topic, question, keys) in enumerate(ds["questions"], 1):
            out.append({
                "source_file": ds["source_file"],
                "id": i,
                "topic": topic,
                "question": question,
                "expected_keys": keys,
            })
    return out

if __name__ == "__main__":
    arr = build_array()
    assert len(arr) == 140, len(arr)
    path = Path(__file__).parent / "passport_rag_questions.json"
    path.write_text(json.dumps(arr, ensure_ascii=False, indent=2), encoding="utf-8")
    print(len(arr))
